public final class ServiceContext {                  // the context object
    private final String requestId;
    private final long tenantId;
    public String requestId() { return requestId; }
    public long tenantId() { return tenantId; }
}

interface Layer { Response handle(Request request, ServiceContext ctx); }

ServiceContext ctx = ServiceContextFactory.create(request);
layerA.handle(request, ctx);   // explicit threading, no ambient lookup

static final ScopedValue<ServiceContext> CONTEXT = ScopedValue.newInstance();

void serve(Request req, Response res) {
    ScopedValue.where(CONTEXT, ServiceContext.of(req))
               .run(() -> application.handle(req, res));   // bounded binding
}

long tenantId() { return CONTEXT.get().tenantId(); }       // any callee
